// ── Data ─────────────────────────────────────────────────────────────────────

class _Term {
  final String transliteration;
  final String arabic;
  final _TermCategory category;
  final String en;
  final String ar;
  final String ur;
  final String es;
  final String fr;
  final String id;
  final String zh;
  final String ja;
  final String bn;
  final String tr;
  final String sw;
  final String de;
  final String nl;
  final String pt;
  final String it;

  const _Term({
    required this.transliteration,
    required this.arabic,
    required this.category,
    required this.en,
    required this.ar,
    required this.ur,
    required this.es,
    required this.fr,
    required this.id,
    required this.zh,
    required this.ja,
    required this.bn,
    required this.tr,
    required this.sw,
    required this.de,
    required this.nl,
    required this.pt,
    required this.it,
  });

  String definition(String lang) {
    switch (lang) {
      case 'ar':
        return ar;
      case 'ur':
        return ur;
      case 'es':
        return es;
      case 'fr':
        return fr;
      case 'id':
        return id;
      case 'zh':
        return zh;
      case 'ja':
        return ja;
      case 'bn':
        return bn;
      case 'tr':
        return tr;
      case 'sw':
        return sw;
      case 'de':
        return de;
      case 'nl':
        return nl;
      case 'pt':
        return pt;
      case 'it':
        return it;
      default:
        return en;
    }
  }
}

enum _TermCategory { pillar, quran, hadith, aqeedah, fiqh, practice, dhikr, history }

extension _TermCategoryExt on _TermCategory {
  String label(AppLocalizations l10n) {
    switch (this) {
      case _TermCategory.pillar:
        return l10n.categoryPillar;
      case _TermCategory.quran:
        return l10n.categoryQuran;
      case _TermCategory.hadith:
        return l10n.categoryHadith;
      case _TermCategory.aqeedah:
        return l10n.categoryAqeedah;
      case _TermCategory.fiqh:
        return l10n.categoryFiqh;
      case _TermCategory.practice:
        return l10n.categoryPractice;
      case _TermCategory.dhikr:
        return l10n.categoryDhikr;
      case _TermCategory.history:
        return l10n.categoryHistory;
    }
  }

  Color get color {
    switch (this) {
      case _TermCategory.pillar:
        return const Color(0xFF2E7D32);
      case _TermCategory.quran:
        return const Color(0xFF1565C0);
      case _TermCategory.hadith:
        return const Color(0xFF4A148C);
      case _TermCategory.aqeedah:
        return const Color(0xFF880E4F);
      case _TermCategory.fiqh:
        return const Color(0xFFBF360C);
      case _TermCategory.practice:
        return const Color(0xFF00695C);
      case _TermCategory.dhikr:
        return const Color(0xFF4E342E);
      case _TermCategory.history:
        return const Color(0xFF1A237E);
    }
  }
}

